// Aizawa attractor - iterate the ODE from a seed-jittered start.
// Each particle lands on a different part of the same attracting set,
// and varying the step count spreads density along the orbit.
vec3 shapeAizawa(float a, float b, float c, float S){
    // tiny jittered start ball near origin (seeds decorrelated by hashing)
    vec3 p = (vec3(fract(a*43.0+0.13), fract(b*91.7+0.41), fract(c*57.3+0.77)) - 0.5) * 0.12;
    const float A=0.95, B=0.7, C=0.6, D=3.5, E=0.25, F=0.1, dt=0.01;
    int iters = 260 + int(a*140.0);            // 260..400 -> spread along manifold
    for(int i=0;i<400;i++){
        if(i>=iters) break;                    // GLSL ES: constant loop bound + break
        float dx = (p.z - B)*p.x - D*p.y;
        float dy =  D*p.x + (p.z - B)*p.y;
        float dz =  C + A*p.z - p.z*p.z*p.z/3.0
                  - (p.x*p.x + p.y*p.y)*(1.0 + E*p.z)
                  + F*p.z*p.x*p.x*p.x;
        p += vec3(dx,dy,dz)*dt;
    }
    // attractor lives roughly in [-1.5,1.5]; 0.42*S fills ~70% of frustum height
    return p * (0.42 * S);
    // PALETTE: color by length(velocity) of the final step ->
    // violet (slow shell) -> cyan -> gold (fast axial spike).
}

// Hopf fibration: seed -> a base point on S^2 (which fiber), then a phase
// along that fiber circle; lift to S^3 and stereographically project to R^3.
// Quantizing the base point to a few values yields a few BIG clean linked
// rings (more legible than a full fill).
vec3 shapeHopf(float a, float b, float c, float S){
    const float TAU = 6.28318530718;
    // quantize base point so we get ~12 bold interlocking rings, not mush
    float ringId   = floor(a * 12.0);
    float cosT     = 2.0*fract(ringId*0.61803398875) - 1.0; // base colatitude, spread
    float baseTheta= acos(clamp(cosT,-1.0,1.0));
    float basePhi  = TAU * fract(ringId*0.7548776662);
    vec3  bp = vec3(sin(baseTheta)*cos(basePhi),
                    sin(baseTheta)*sin(basePhi),
                    cos(baseTheta));            // (x,y,z) on S^2
    float t  = TAU * b;                          // phase along the fiber circle
    float k  = 1.0 / sqrt(2.0*(1.0 + bp.z) + 1e-4);
    vec4  P  = vec4((1.0+bp.z)*cos(t),
                    bp.x*sin(t) - bp.y*cos(t),
                    bp.x*cos(t) + bp.y*sin(t),
                    (1.0+bp.z)*sin(t)) * k;       // point on S^3
    vec3  q  = P.xyz / (1.0 - P.w + 1e-3);        // stereographic S^3 -> R^3
    // jitter slightly along c so each ring has a little tube thickness
    q += (vec3(fract(c*71.3),fract(c*131.7),fract(c*197.1))-0.5)*0.04;
    return q * (0.28 * S);
}

// (p,q) torus knot, inflated into a volumetric tube via a Frenet-ish frame.
// a -> position along the curve; b,c -> uniform fill of the tube cross-section.
vec3 shapeTorusKnot(float a, float b, float c, float S){
    const float TAU = 6.28318530718;
    const float P = 3.0, Q = 7.0;     // (3,7) braid; swap per loop for variety
    const float R = 1.0, rMinor = 0.45, rTube = 0.16;
    float t  = a * TAU;
    float cq = cos(Q*t), sq = sin(Q*t);
    float ring = R + rMinor*cq;
    vec3  C = vec3(ring*cos(P*t), ring*sin(P*t), rMinor*sq);   // core curve
    // analytic tangent dC/dt
    vec3 T = vec3(-rMinor*Q*sq*cos(P*t) - ring*P*sin(P*t),
                  -rMinor*Q*sq*sin(P*t) + ring*P*cos(P*t),
                   rMinor*Q*cq);
    T = normalize(T);
    vec3 N = normalize(cross(T, vec3(0.0,0.0,1.0)));
    vec3 B = cross(T, N);
    float ang = b * TAU;
    float rad = sqrt(c) * rTube;       // sqrt -> uniform disc (no center clump)
    vec3 pos = C + rad*(cos(ang)*N + sin(ang)*B);
    return pos * (0.55 * S);
}

// DNA double helix: two antiparallel sugar-phosphate strands + base-pair rungs.
// a -> height along the axis; b classifies particle into strandA / strandB / rung;
// c -> radial thickness so strands read as ribbons, not lines.
vec3 shapeDNA(float a, float b, float c, float S){
    const float TAU = 6.28318530718;
    const float TWISTS = 6.0;          // full turns over the length
    const float HEIGHT = 2.0;
    const float RADIUS = 0.55;
    float yy  = (a - 0.5) * HEIGHT;
    float ang = a * TWISTS * TAU;
    vec3 strandA = vec3(cos(ang)*RADIUS,        yy, sin(ang)*RADIUS);
    vec3 strandB = vec3(cos(ang+3.14159)*RADIUS, yy, sin(ang+3.14159)*RADIUS);
    vec3 pos;
    if(b < 0.42){          // strand A (cyan)
        pos = strandA;
    } else if(b < 0.84){   // strand B (violet)
        pos = strandB;
    } else {               // base-pair rung (gold), interpolate across the ladder
        float k = fract(b * 53.0);
        pos = mix(strandA, strandB, k);
    }
    // ribbon thickness: jitter in a small ball, sqrt for even fill
    float rad = sqrt(c) * 0.06;
    float ja  = fract(c*131.7)*TAU, jb = fract(c*71.3)*3.14159;
    pos += rad * vec3(sin(jb)*cos(ja), cos(jb), sin(jb)*sin(ja));
    return pos * (0.62 * S);
}

// Barred spiral galaxy: log-spiral arms + exponential disc thickness + bright core.
// a -> which arm + per-arm scatter; b -> radius (sqrt for centre concentration);
// c -> vertical disc jitter and core bulge.
vec3 shapeGalaxy(float a, float b, float c, float S){
    const float TAU = 6.28318530718;
    const float N_ARMS = 4.0;
    const float TWIST  = 2.6;          // arm winding
    float arm  = floor(a * N_ARMS);
    float t    = sqrt(b);              // 0..1 radial, sqrt concentrates centre
    float r    = t;
    float jit  = (fract(a*97.13) - 0.5) * 0.35 * (1.0 - t); // arms tighten outward
    float ang  = arm * TAU / N_ARMS + t * TWIST * TAU + jit;
    // disc thickness: thick bulge at centre, thin at rim
    float yy = (fract(c*53.7) - 0.5) * 0.14 * exp(-2.5*r);
    vec3 pos = vec3(cos(ang)*r, yy, sin(ang)*r);
    // central bulge: a fraction of particles form the spherical core
    if(b < 0.06){
        float rr = pow(fract(c*191.3), 0.5) * 0.12;
        float th = fract(a*311.7)*TAU, ph = acos(2.0*fract(c*131.1)-1.0);
        pos = vec3(rr*sin(ph)*cos(th), rr*cos(ph), rr*sin(ph)*sin(th));
    }
    return pos * (1.30 * S);
    // PALETTE: gold core (small r) -> emerald mid-disc -> violet/cyan rim by r.
}

// Gielis superformula, spherical product of two superformulas (surface-sampled).
// a -> longitude theta, b -> latitude phi, c -> thin surface-shell jitter.
// Swap the (m,n1,n2,n3) set per loop to morph through the bestiary.
float superR(float ang, float m, float n1, float n2, float n3){
    float t  = m * ang * 0.25;
    float c1 = pow(abs(cos(t)), n2);
    float c2 = pow(abs(sin(t)), n3);
    return pow(c1 + c2 + 1e-6, -1.0/n1);
}
vec3 shapeSupershape(float a, float b, float c, float S){
    const float PI = 3.14159265359;
    float theta = (a*2.0 - 1.0) * PI;        // -PI..PI
    float phi   = (b - 0.5) * PI;            // -PI/2..PI/2
    // spiky sea-urchin: m=7,n1=0.2,n2=1.7,n3=1.7
    // (crystal m=4,n1=60,n2=55,n3=30 | star m=5,n1=0.1,n2=1.7,n3=1.7)
    float m=7.0, n1=0.2, n2=1.7, n3=1.7;
    float r1 = superR(theta, m, n1, n2, n3);
    float r2 = superR(phi,   m, n1, n2, n3);
    vec3 pos = vec3(r1*cos(theta) * r2*cos(phi),
                    r1*sin(theta) * r2*cos(phi),
                    r2*sin(phi));
    // tame extreme spikes so framing stays stable, then add a thin shell jitter
    pos = normalize(pos) * pow(length(pos), 0.6);
    pos *= (1.0 + (c - 0.5)*0.04);
    return pos * (0.85 * S);
}

// TEXT beat. PREFERRED (zero rejection): on the CPU, draw the word to a canvas,
// read alpha, collect every pixel with a>0.5 into inside[], and for particle i
// write target = vec3((px/W-0.5)*S*aspect, -(py/H-0.5)*S, (hash-0.5)*depth)
// straight into the position FBO. No per-frame cost.
//
// SHADER fallback below: sample a bound alpha mask uMask (NearestFilter) and
// relax outside particles toward the glyph along the alpha gradient.
uniform sampler2D uMask;     // word rasterized to alpha; e.g. 1024x256
uniform float     uAspect;   // mask width/height
vec3 shapeText(float a, float b, float c, float S){
    const float DEPTH = 0.10;
    vec2 uv = vec2(a, b);                       // candidate glyph UV
    // a few relaxation steps: walk toward denser alpha so strays land on letters
    for(int i=0;i<4;i++){
        float al = texture2D(uMask, uv).a;
        if(al > 0.5) break;
        float e = 1.0/256.0;
        float gx = texture2D(uMask, uv+vec2(e,0.0)).a - texture2D(uMask, uv-vec2(e,0.0)).a;
        float gy = texture2D(uMask, uv+vec2(0.0,e)).a - texture2D(uMask, uv-vec2(0.0,e)).a;
        vec2 g = vec2(gx,gy);
        uv += normalize(g + 1e-5) * 0.03;       // climb the alpha field
    }
    vec3 pos = vec3((uv.x - 0.5) * uAspect,     // centre + correct aspect
                    -(uv.y - 0.5),              // flip: texture v is top-down
                    (c - 0.5) * DEPTH);         // slab depth so it isn't flat
    return pos * (0.95 * S);
    // PALETTE: glyph core gold/emerald; edge/stray particles cyan->violet,
    // driven by step(uProgress, noise) for the assemble/dissolve dust.
}
